/**
 * DM Assistant — Multiplayer Server
 * 
 * Express + Socket.io server that enables real-time multiplayer
 * for the DM Assistant. The DM's PC runs this server; players
 * connect through a browser.
 * 
 * Usage:
 *   npm run server        (server only)
 *   npm run multiplayer   (server + Vite dev server)
 */

import express from 'express';
import { createServer } from 'http';
import { Server as SocketIOServer, Socket } from 'socket.io';
import { existsSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';
import { networkInterfaces } from 'os';

/** Returns all non-loopback IPv4 addresses on this machine (LAN + Hamachi). */
function getLanIps(): string[] {
    const results: string[] = [];
    const nets = networkInterfaces();
    for (const iface of Object.values(nets)) {
        for (const net of iface ?? []) {
            if (net.family === 'IPv4' && !net.internal) {
                results.push(net.address);
            }
        }
    }
    return results;
}

import { roomManager, type PlayerInfo } from './roomManager.js';
import { saveState, loadState, initDataDir } from './stateManager.js';
import { buildFilteredState, filterChat } from './playerFilter.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// ─── Configuration ───────────────────────────────────────────
const PORT = parseInt(process.env.PORT || '3001', 10);
const DIST_PATH = join(__dirname, '..', 'dist');

// ─── Express Setup ───────────────────────────────────────────
const app = express();
app.use(express.json({ limit: '10mb' }));

// Health check endpoint
app.get('/api/health', (_req, res) => {
    res.json({ status: 'ok', uptime: process.uptime() });
});

// Network info endpoint — lets the frontend show LAN join URLs
app.get('/api/network-info', (_req, res) => {
    res.json({ lanIps: getLanIps(), port: PORT });
});

// Serve built React app in production
if (existsSync(DIST_PATH)) {
    app.use(express.static(DIST_PATH));

    // SPA fallback: serve index.html for any non-API route
    app.get('{*path}', (_req, res) => {
        res.sendFile(join(DIST_PATH, 'index.html'));
    });
}

// ─── HTTP + Socket.io Setup ──────────────────────────────────
const httpServer = createServer(app);
const io = new SocketIOServer(httpServer, {
    cors: {
        origin: true,  // Allow any origin — needed for Cloudflare Tunnel + LAN IPs
        methods: ['GET', 'POST'],
    },
    maxHttpBufferSize: 10e6, // 10MB — large enough for map images
    pingTimeout: 60000,
    pingInterval: 25000,
});

// ─── In-Memory Game State Per Room ───────────────────────────
interface RoomGameState {
    characters: any[];
    combat: any;
    chat: any[];
    /** Independently-pushed map (can be from Navigator or Combat). */
    activeMap: any | null;
}

const roomStates = new Map<string, RoomGameState>();

function getOrCreateRoomState(roomCode: string): RoomGameState {
    if (roomStates.has(roomCode)) {
        return roomStates.get(roomCode)!;
    }

    // Try loading from disk
    const characters = loadState<any[]>(roomCode, 'characters') ?? [];
    const combat = loadState<any>(roomCode, 'combat') ?? null;
    const chat = loadState<any[]>(roomCode, 'chat') ?? [];

    const state: RoomGameState = { characters, combat, chat, activeMap: null };
    roomStates.set(roomCode, state);
    return state;
}

function broadcastToPlayers(roomCode: string): void {
    const room = roomManager.getRoom(roomCode);
    if (!room) return;

    const state = getOrCreateRoomState(roomCode);
    const players = roomManager.getPlayers(roomCode);

    for (const player of players) {
        const filtered = buildFilteredState(
            { characters: state.characters, combat: state.combat, chat: state.chat },
            player,
            state.activeMap,
        );
        io.to(player.socketId).emit('state:sync', filtered);
    }
}

function broadcastRoomInfo(roomCode: string): void {
    const room = roomManager.getRoom(roomCode);
    if (!room) return;

    const serialized = roomManager.serializeRoom(room);

    // Send to everyone in the room
    for (const [socketId] of room.players) {
        io.to(socketId).emit('room:info', serialized);
    }
}

// ─── Socket.io Event Handlers ────────────────────────────────
io.on('connection', (socket: Socket) => {
    console.log(`[Server] Client connected: ${socket.id}`);

    // Prevent uncaught errors from crashing the server
    socket.on('error', (err) => {
        console.error(`[Server] Socket error for ${socket.id}:`, err.message);
    });

    // ── Room Management ──────────────────────────────────────

    /**
     * DM creates a new room.
     * Response: { success, code, room }
     */
    socket.on('room:create', (callback: (res: any) => void) => {
        const { code, room } = roomManager.createRoom(socket.id);
        getOrCreateRoomState(code); // Initialize empty state

        console.log(`[Server] Room created: ${code} by ${socket.id}`);

        callback({
            success: true,
            code,
            room: roomManager.serializeRoom(room),
        });
    });

    /**
     * Player joins a room.
     * Payload: { code, playerName }
     * Response: { success, room, player, error? }
     */
    socket.on('room:join', (payload: { code: string; playerName: string }, callback: (res: any) => void) => {
        const result = roomManager.joinRoom(payload.code, socket.id, payload.playerName);

        if (!result.success) {
            callback({ success: false, error: result.reason });
            return;
        }

        console.log(`[Server] Player "${payload.playerName}" joined room ${payload.code}`);

        // Send room info to everyone
        broadcastRoomInfo(result.room.code);

        // Send current game state to the new player
        const state = getOrCreateRoomState(result.room.code);
        const filtered = buildFilteredState(state, result.player);
        socket.emit('state:sync', filtered);

        callback({
            success: true,
            room: roomManager.serializeRoom(result.room),
            player: result.player,
        });
    });

    /**
     * DM assigns a character to a player.
     * Payload: { playerSocketId, characterId }
     */
    socket.on('room:assign-character', (payload: { playerSocketId: string; characterId: string }, callback?: (res: any) => void) => {
        if (!roomManager.isDM(socket.id)) {
            callback?.({ success: false, error: 'Only the DM can assign characters.' });
            return;
        }

        const roomCode = roomManager.getRoomCode(socket.id);
        if (!roomCode) {
            callback?.({ success: false, error: 'Not in a room.' });
            return;
        }

        const success = roomManager.assignCharacter(roomCode, payload.playerSocketId, payload.characterId);
        if (!success) {
            callback?.({ success: false, error: 'Could not assign character.' });
            return;
        }

        console.log(`[Server] Character ${payload.characterId} assigned to ${payload.playerSocketId} in room ${roomCode}`);

        // Re-broadcast state so the player gets their character
        broadcastToPlayers(roomCode);
        broadcastRoomInfo(roomCode);
        callback?.({ success: true });
    });

    /**
     * DM toggles sheet editing for a player.
     * Payload: { playerSocketId, canEdit }
     */
    socket.on('room:toggle-edit', (payload: { playerSocketId: string; canEdit: boolean }, callback?: (res: any) => void) => {
        if (!roomManager.isDM(socket.id)) {
            callback?.({ success: false, error: 'Only the DM can toggle editing.' });
            return;
        }

        const roomCode = roomManager.getRoomCode(socket.id);
        if (!roomCode) return;

        roomManager.toggleSheetEdit(roomCode, payload.playerSocketId, payload.canEdit);
        broadcastRoomInfo(roomCode);
        callback?.({ success: true });
    });

    /**
     * DM kicks a player.
     * Payload: { playerSocketId }
     */
    socket.on('room:kick', (payload: { playerSocketId: string }, callback?: (res: any) => void) => {
        if (!roomManager.isDM(socket.id)) {
            callback?.({ success: false, error: 'Only the DM can kick players.' });
            return;
        }

        const roomCode = roomManager.getRoomCode(socket.id);
        if (!roomCode) return;

        // Notify the kicked player
        io.to(payload.playerSocketId).emit('room:kicked', { reason: 'You were removed by the DM.' });

        // Disconnect them from the room
        roomManager.removePlayer(payload.playerSocketId);
        broadcastRoomInfo(roomCode);
        callback?.({ success: true });
    });

    // ── State Synchronization ────────────────────────────────

    /**
     * DM pushes full game state.
     * This is called when the DM syncs their local Zustand state to the server.
     * Payload: { characters, combat }
     */
    socket.on('state:push', (payload: { characters?: any[]; combat?: any }) => {
        if (!roomManager.isDM(socket.id)) {
            console.warn(`[Server] Non-DM tried to push state: ${socket.id}`);
            return;
        }

        const roomCode = roomManager.getRoomCode(socket.id);
        if (!roomCode) return;

        const state = getOrCreateRoomState(roomCode);

        if (payload.characters !== undefined) {
            state.characters = payload.characters;
            saveState(roomCode, 'characters', payload.characters);
        }

        if (payload.combat !== undefined) {
            state.combat = payload.combat;
            saveState(roomCode, 'combat', payload.combat);
        }

        roomManager.touchRoom(roomCode);
        broadcastToPlayers(roomCode);
    });

    /**
     * DM pushes a specific map to players (independent of the combat encounter).
     * Payload: BattleMapState (the full map data)
     */
    socket.on('map:push', (mapData: any) => {
        if (!roomManager.isDM(socket.id)) return;

        const roomCode = roomManager.getRoomCode(socket.id);
        if (!roomCode) return;

        const state = getOrCreateRoomState(roomCode);
        state.activeMap = mapData;

        console.log(`[Server] DM pushed active map to room ${roomCode}`);
        roomManager.touchRoom(roomCode);
        broadcastToPlayers(roomCode);
    });

    /**
     * DM clears the active map — players see a blank map area.
     */
    socket.on('map:clear', () => {
        if (!roomManager.isDM(socket.id)) return;

        const roomCode = roomManager.getRoomCode(socket.id);
        if (!roomCode) return;

        const state = getOrCreateRoomState(roomCode);
        state.activeMap = null;

        console.log(`[Server] DM cleared active map from room ${roomCode}`);
        broadcastToPlayers(roomCode);
    });

    /**
     * Player moves their own token.
     * Server validates that the token belongs to this player, then broadcasts.
     * Payload: { tokenId, newPosition: { col, row } }
     */
    socket.on('token:move', (payload: { tokenId: string; newPosition: { col: number; row: number } }, callback?: (res: any) => void) => {
        const player = roomManager.getPlayer(socket.id);
        const roomCode = roomManager.getRoomCode(socket.id);
        if (!player || !roomCode) {
            callback?.({ success: false, error: 'Not in a room.' });
            return;
        }

        const state = getOrCreateRoomState(roomCode);
        const combat = state.combat;
        if (!combat?.battleMap?.tokens) {
            callback?.({ success: false, error: 'No active battle map.' });
            return;
        }

        // Find the token
        const token = combat.battleMap.tokens.find((t: any) => t.id === payload.tokenId);
        if (!token) {
            callback?.({ success: false, error: 'Token not found.' });
            return;
        }

        // Validate ownership: the token's combatantId must match a combatant
        // whose sourceId matches this player's characterId
        const combatant = combat.combatants?.find((c: any) => c.id === token.combatantId);
        if (!combatant || combatant.sourceId !== player.characterId) {
            callback?.({ success: false, error: 'You can only move your own token.' });
            return;
        }

        // Apply the move
        token.position = payload.newPosition;
        saveState(roomCode, 'combat', combat);

        // Broadcast to DM and all players
        const room = roomManager.getRoom(roomCode);
        if (room) {
            // Notify the DM of the token move
            io.to(room.dmSocketId).emit('token:moved', {
                tokenId: payload.tokenId,
                newPosition: payload.newPosition,
                movedBy: player.name,
            });
        }

        broadcastToPlayers(roomCode);
        callback?.({ success: true });
    });

    // ── Chat / Dice ──────────────────────────────────────────

    /**
     * Any user sends a chat message or dice roll.
     * Payload: { text, isRoll?, rollResult?, isWhisper?, recipientId? }
     */
    socket.on('chat:message', (payload: {
        text: string;
        isRoll?: boolean;
        rollResult?: string;
        isWhisper?: boolean;
        recipientId?: string;
    }) => {
        const player = roomManager.getPlayer(socket.id);
        const roomCode = roomManager.getRoomCode(socket.id);
        if (!player || !roomCode) return;

        const state = getOrCreateRoomState(roomCode);
        const message = {
            id: crypto.randomUUID(),
            senderId: socket.id,
            senderName: player.name,
            senderRole: player.role,
            text: payload.text,
            isRoll: payload.isRoll ?? false,
            rollResult: payload.rollResult,
            isWhisper: payload.isWhisper ?? false,
            recipientId: payload.recipientId,
            timestamp: Date.now(),
        };

        state.chat.push(message);

        // Keep chat log at a reasonable size (last 500 messages)
        if (state.chat.length > 500) {
            state.chat = state.chat.slice(-500);
        }

        saveState(roomCode, 'chat', state.chat);

        // Broadcast to room — each player gets filtered chat
        const room = roomManager.getRoom(roomCode);
        if (room) {
            for (const [socketId, p] of room.players) {
                const filteredMessages = filterChat(state.chat, p);
                io.to(socketId).emit('chat:sync', filteredMessages);
            }
        }
    });

    // ── Player Sheet Edit (when DM allows it) ────────────────

    /**
     * Player updates their own character sheet (only when canEditSheet is true).
     * Payload: { characterId, updates }
     */
    socket.on('character:update', (payload: { characterId: string; updates: any }, callback?: (res: any) => void) => {
        const player = roomManager.getPlayer(socket.id);
        const roomCode = roomManager.getRoomCode(socket.id);
        if (!player || !roomCode) {
            callback?.({ success: false, error: 'Not in a room.' });
            return;
        }

        // Validate: player can only edit their own character
        if (payload.characterId !== player.characterId) {
            callback?.({ success: false, error: 'You can only edit your own character.' });
            return;
        }

        // Validate: DM must have enabled editing
        if (!player.canEditSheet && player.role !== 'dm') {
            callback?.({ success: false, error: 'Sheet editing is locked by the DM.' });
            return;
        }

        const state = getOrCreateRoomState(roomCode);
        const charIndex = state.characters.findIndex((c: any) => c.id === payload.characterId);
        if (charIndex === -1) {
            callback?.({ success: false, error: 'Character not found.' });
            return;
        }

        // Apply updates
        state.characters[charIndex] = { ...state.characters[charIndex], ...payload.updates };
        saveState(roomCode, 'characters', state.characters);

        // Notify DM
        const room = roomManager.getRoom(roomCode);
        if (room) {
            io.to(room.dmSocketId).emit('character:updated', {
                characterId: payload.characterId,
                updates: payload.updates,
                updatedBy: player.name,
            });
        }

        broadcastToPlayers(roomCode);
        callback?.({ success: true });
    });

    // ── Disconnection ────────────────────────────────────────
    socket.on('disconnect', (reason) => {
        console.log(`[Server] Client disconnected: ${socket.id} (${reason})`);

        const result = roomManager.removePlayer(socket.id);
        if (result) {
            if (result.wasEmpty) {
                // DM left: clean up room state (keep on disk for resuming later)
                console.log(`[Server] DM left room ${result.roomCode}. Room destroyed.`);
                roomStates.delete(result.roomCode);
            } else {
                broadcastRoomInfo(result.roomCode);
            }
        }
    });
});

// ─── Stale Room Cleanup (every hour) ────────────────────────
setInterval(() => {
    const cleaned = roomManager.cleanupStaleRooms();
    if (cleaned > 0) {
        console.log(`[Server] Cleaned up ${cleaned} stale rooms.`);
    }
}, 60 * 60 * 1000);

// ─── Process-Level Error Handling ────────────────────────────
// Prevent the server from crashing on unhandled errors
process.on('uncaughtException', (err) => {
    console.error('[Server] Uncaught exception (server stays alive):', err.message);
});
process.on('unhandledRejection', (reason) => {
    console.error('[Server] Unhandled rejection (server stays alive):', reason);
});

// ─── Start Server ────────────────────────────────────────────
initDataDir();

httpServer.listen(PORT, '0.0.0.0', () => {
    const lanIps = getLanIps();
    console.log('');
    console.log('═══════════════════════════════════════════════');
    console.log('  DM Assistant — Multiplayer Server');
    console.log('═══════════════════════════════════════════════');
    console.log(`  📡 DM Dashboard:  http://localhost:5173`);
    console.log(`  📡 DM Lobby:      http://localhost:5173/lobby`);
    console.log('');
    if (lanIps.length > 0) {
        console.log('  🌐 Share these URLs with your players (same network):');
        lanIps.forEach(ip => {
            console.log(`     http://${ip}:5173/lobby`);
        });
    } else {
        console.log('  ⚠️  No LAN IPs found. Are you connected to a network?');
    }
    console.log('');
    console.log(`  🔌 WebSocket:     ws://localhost:${PORT}`);
    console.log(`  📁 Data dir:      server/data/`);
    console.log('═══════════════════════════════════════════════');
    console.log('');
    console.log('  Waiting for connections...');
    console.log('');
});

/**
 * Player Filter
 * 
 * Filters game state before sending it to a specific player.
 * Players should only see:
 *   - Their own character sheet
 *   - Public combat info (HP, AC, position of all combatants — but no hidden DM notes)
 *   - The map with fog of war applied
 *   - Chat messages addressed to them or public
 *
 * Players should NOT see:
 *   - Other players' character sheets
 *   - DM notes, navigator state, campaign management
 *   - Monster statblock internals (STR/DEX/etc unless revealed)
 *   - Full fog of war data (they only see revealed areas)
 */

import type { PlayerInfo } from './roomManager.js';

/**
 * Data shapes — these match the Zustand store structures on the client.
 * We use `any` here because the server doesn't import client types;
 * it treats state as opaque JSON and only filters specific fields.
 */
/* eslint-disable @typescript-eslint/no-explicit-any */

export interface FilteredStateBundle {
    characters: any;
    combat: any;
    map: any;
    chat: any;
}

/**
 * Filter character data for a specific player.
 * They only see the character assigned to them via characterId.
 */
export function filterCharacters(allCharacters: any[], player: PlayerInfo): any[] {
    if (!player.characterId) return [];

    const myChar = allCharacters.find((c: any) => c.id === player.characterId);
    return myChar ? [myChar] : [];
}

/**
 * Filter combat/encounter data for a player.
 * They see:
 *   - All combatants' names, HP, AC, conditions, position, initiative (public info)
 *   - The current turn, round number
 *   - Combat log (public entries)
 * They don't see:
 *   - Monster ability scores, spellcasting ability, internal statblock data
 *   - DM-only log entries
 *   - Hidden combatants (unless the DM has revealed them)
 */
export function filterCombat(encounter: any, player: PlayerInfo): any {
    if (!encounter) return null;

    const filteredCombatants = (encounter.combatants || []).map((c: any) => {
        // Public info for all combatants
        const publicData: any = {
            id: c.id,
            sourceId: c.sourceId,
            type: c.type,
            name: c.name,
            portraitUrl: c.portraitUrl,
            ac: c.ac,
            maxHp: c.maxHp,
            currentHp: c.currentHp,
            tempHp: c.tempHp,
            conditions: c.conditions,
            isDead: c.isDead,
            initiativeScore: c.initiativeScore,
            gridPosition: c.gridPosition,
            tokenSize: c.tokenSize,
            elevation: c.elevation,
            isConcentrating: c.isConcentrating,
            concentratingOn: c.concentratingOn,
            deathSaves: c.type === 'player' ? c.deathSaves : undefined,
            speed: c.speed,
        };

        // If it's this player's character, include full data
        if (c.sourceId === player.characterId || c.id === player.characterId) {
            return {
                ...publicData,
                abilityScores: c.abilityScores,
                spellSlots: c.spellSlots,
                hasAction: c.hasAction,
                hasBonusAction: c.hasBonusAction,
                hasReaction: c.hasReaction,
                spellcastingAbility: c.spellcastingAbility,
                spellSaveDc: c.spellSaveDc,
                spellAttackMod: c.spellAttackMod,
                proficiencyBonus: c.proficiencyBonus,
                savingThrowProficiencies: c.savingThrowProficiencies,
                resistances: c.resistances,
                immunities: c.immunities,
                vulnerabilities: c.vulnerabilities,
                exhaustion: c.exhaustion,
            };
        }

        return publicData;
    });

    const filteredLog = (encounter.log || []).filter((entry: any) => {
        // Hide DM-only entries
        if (entry.dmOnly) return false;
        return true;
    });

    return {
        id: encounter.id,
        title: encounter.title,
        isActive: encounter.isActive,
        round: encounter.round,
        activeCombatantId: encounter.activeCombatantId,
        combatants: filteredCombatants,
        log: filteredLog,
        turnState: encounter.turnState,
    };
}

/**
 * Filter map/battle state for a player.
 * Apply fog of war: the player sees only the revealed portions.
 * Tokens are visible in revealed areas.
 */
export function filterMap(battleMap: any, _player: PlayerInfo): any {
    if (!battleMap) return null;

    // For now, send the entire map to players.
    // Fog of war is rendered client-side — the client draws the fog shapes
    // over unrevealed areas. In a future iteration, we could strip tokens
    // in unrevealed cells, but for MVP the fog rendering on the client
    // is sufficient (matching how Foundry VTT handles it).
    return {
        gridWidth: battleMap.gridWidth,
        gridHeight: battleMap.gridHeight,
        cellSizePx: battleMap.cellSizePx,
        gridColor: battleMap.gridColor,
        backgroundColor: battleMap.backgroundColor,
        tokens: battleMap.tokens,
        // Strip DM-only shapes — players must not see hidden annotations
        shapes: (battleMap.shapes ?? []).filter((s: any) => s.visibility !== 'dm-only'),
        freehandPaths: battleMap.freehandPaths,
        backgroundImageUrl: battleMap.backgroundImageUrl,
        backgroundOffset: battleMap.backgroundOffset,
        backgroundScaleX: battleMap.backgroundScaleX,
        backgroundScaleY: battleMap.backgroundScaleY,
        fogOfWar: (battleMap.fogOfWar ?? []).filter((s: any) => s.visibility !== 'dm-only'),
        fogOfWarFreehand: battleMap.fogOfWarFreehand,
    };
}

/**
 * Filter chat messages for a player.
 * Public messages are visible to all.
 * Whispers are only visible to the sender and the recipient.
 */
export function filterChat(chatLog: any[], player: PlayerInfo): any[] {
    if (!chatLog) return [];

    return chatLog.filter((msg: any) => {
        // Public messages
        if (!msg.isWhisper) return true;

        // Whisper: visible to sender and recipient
        if (msg.recipientId === player.socketId) return true;
        if (msg.senderId === player.socketId) return true;

        return false;
    });
}

/**
 * Build a complete filtered state bundle for a specific player.
 * 
 * @param activeMap - Optional map pushed directly by DM. When present, overrides
 *                    the combat battleMap as the map shown to players.
 */
export function buildFilteredState(
    fullState: {
        characters: any[];
        combat: any;
        chat: any[];
    },
    player: PlayerInfo,
    activeMap?: any | null,
): FilteredStateBundle {
    const combat = fullState.combat;
    // Prefer DM-pushed activeMap if present; fall back to combat battleMap
    const battleMap = activeMap !== undefined ? activeMap : (combat?.battleMap ?? null);

    return {
        characters: filterCharacters(fullState.characters, player),
        combat: filterCombat(combat, player),
        map: filterMap(battleMap, player),
        chat: filterChat(fullState.chat, player),
    };
}

/**
 * Player Dice & Chat Panel
 * 
 * Shared dice rolling + chat log visible to all connected users.
 * Players can:
 *   - Roll any die (d4, d6, d8, d10, d12, d20, d100)
 *   - Type custom rolls (e.g., "2d6+3")
 *   - Send chat messages
 * 
 * DM whispers show only to the DM and the recipient.
 */

import { useState, useRef, useEffect } from 'react';
import { Dice1, Send, MessageCircle } from 'lucide-react';
import { useSessionStore } from '../../multiplayer/sessionStore';
import type { ChatMessage } from '../../multiplayer/types';

const DICE_TYPES = [4, 6, 8, 10, 12, 20, 100] as const;

function rollDice(sides: number, count: number = 1): { total: number; rolls: number[] } {
    const rolls: number[] = [];
    for (let i = 0; i < count; i++) {
        rolls.push(Math.floor(Math.random() * sides) + 1);
    }
    return { total: rolls.reduce((a, b) => a + b, 0), rolls };
}

function parseCustomRoll(input: string): { total: number; description: string } | null {
    // Match patterns like "2d6+3", "1d20", "4d8-2", "d6"
    const match = input.trim().match(/^(\d*)d(\d+)([+-]\d+)?$/i);
    if (!match) return null;

    const count = parseInt(match[1] || '1', 10);
    const sides = parseInt(match[2], 10);
    const modifier = parseInt(match[3] || '0', 10);

    if (count < 1 || count > 100 || sides < 1 || sides > 1000) return null;

    const { total, rolls } = rollDice(sides, count);
    const modifiedTotal = total + modifier;
    const modStr = modifier > 0 ? `+${modifier}` : modifier < 0 ? `${modifier}` : '';
    const rollsStr = rolls.length <= 10 ? ` [${rolls.join(', ')}]` : '';

    return {
        total: modifiedTotal,
        description: `${count}d${sides}${modStr}${rollsStr} = **${modifiedTotal}**`,
    };
}

function formatTimestamp(ts: number): string {
    const date = new Date(ts);
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
}

export function PlayerDiceChat() {
    const [message, setMessage] = useState('');
    const [activeTab, setActiveTab] = useState<'chat' | 'dice'>('dice');
    const chatEndRef = useRef<HTMLDivElement>(null);

    const { chatMessages, sendChatMessage, sendDiceRoll, role } = useSessionStore();

    // Auto-scroll to bottom when new messages arrive
    useEffect(() => {
        chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [chatMessages]);

    const handleQuickRoll = (sides: number) => {
        const { total, rolls } = rollDice(sides);
        const rollStr = rolls.length <= 10 ? ` [${rolls.join(', ')}]` : '';
        const description = `1d${sides}${rollStr} = **${total}**`;
        sendDiceRoll(`🎲 Rolled 1d${sides}`, description);
    };

    const handleSendMessage = () => {
        const text = message.trim();
        if (!text) return;

        // Check if it's a dice command
        const rollResult = parseCustomRoll(text);
        if (rollResult) {
            sendDiceRoll(`🎲 Rolled ${text}`, rollResult.description);
        } else {
            sendChatMessage(text);
        }

        setMessage('');
    };

    const renderMessage = (msg: ChatMessage) => {
        const isDM = msg.senderRole === 'dm';
        const isRoll = msg.isRoll;
        const isWhisper = msg.isWhisper;

        return (
            <div
                key={msg.id}
                className={`px-3 py-2 rounded-lg text-sm ${
                    isWhisper
                        ? 'bg-purple-900/30 border border-purple-700/30'
                        : isRoll
                        ? 'bg-amber-900/20 border border-amber-700/20'
                        : isDM
                        ? 'bg-stone-800/80'
                        : 'bg-stone-800/40'
                }`}
            >
                <div className="flex items-center gap-2 mb-1">
                    <span className={`font-semibold text-xs ${isDM ? 'text-amber-400' : 'text-blue-400'}`}>
                        {msg.senderName}
                    </span>
                    {isWhisper && (
                        <span className="text-purple-400 text-[10px] uppercase tracking-wider">whisper</span>
                    )}
                    <span className="text-stone-600 text-[10px] ml-auto">
                        {formatTimestamp(msg.timestamp)}
                    </span>
                </div>
                <div className="text-stone-300">
                    {isRoll && msg.rollResult ? (
                        <div>
                            <span className="text-stone-400">{msg.text}</span>
                            <div className="text-amber-300 font-mono mt-1"
                                 dangerouslySetInnerHTML={{ 
                                     __html: msg.rollResult.replace(/\*\*(.*?)\*\*/g, '<strong class="text-amber-200 text-lg">$1</strong>') 
                                 }}
                            />
                        </div>
                    ) : (
                        msg.text
                    )}
                </div>
            </div>
        );
    };

    return (
        <div className="flex flex-col h-full bg-stone-900/50 border border-stone-700/50 rounded-xl overflow-hidden">
            {/* Tabs */}
            <div className="flex border-b border-stone-700/50">
                <button
                    onClick={() => setActiveTab('dice')}
                    className={`flex-1 flex items-center justify-center gap-2 px-4 py-3 text-sm font-medium transition-colors ${
                        activeTab === 'dice'
                            ? 'text-amber-300 border-b-2 border-amber-400 bg-stone-800/50'
                            : 'text-stone-500 hover:text-stone-300'
                    }`}
                >
                    <Dice1 className="w-4 h-4" />
                    Dice
                </button>
                <button
                    onClick={() => setActiveTab('chat')}
                    className={`flex-1 flex items-center justify-center gap-2 px-4 py-3 text-sm font-medium transition-colors ${
                        activeTab === 'chat'
                            ? 'text-blue-300 border-b-2 border-blue-400 bg-stone-800/50'
                            : 'text-stone-500 hover:text-stone-300'
                    }`}
                >
                    <MessageCircle className="w-4 h-4" />
                    Chat
                    {chatMessages.length > 0 && (
                        <span className="bg-blue-600/40 text-blue-300 text-[10px] px-1.5 py-0.5 rounded-full">
                            {chatMessages.length}
                        </span>
                    )}
                </button>
            </div>

            {/* Dice Quick Roll Buttons */}
            {activeTab === 'dice' && (
                <div className="p-3 border-b border-stone-700/30">
                    <div className="grid grid-cols-4 gap-2">
                        {DICE_TYPES.map((sides) => (
                            <button
                                key={sides}
                                onClick={() => handleQuickRoll(sides)}
                                className="bg-stone-800 hover:bg-stone-700 border border-stone-600/50
                                           text-stone-200 rounded-lg py-2.5 text-sm font-mono
                                           transition-all hover:scale-105 hover:border-amber-500/50
                                           active:scale-95"
                            >
                                d{sides}
                            </button>
                        ))}
                        <button
                            onClick={() => {
                                // Roll 2d20 (advantage)
                                const { rolls } = rollDice(20, 2);
                                const max = Math.max(...rolls);
                                sendDiceRoll(
                                    '🎲 Rolled 2d20 (Advantage)',
                                    `[${rolls.join(', ')}] → **${max}**`
                                );
                            }}
                            className="bg-emerald-900/30 hover:bg-emerald-900/50 border border-emerald-600/30
                                       text-emerald-300 rounded-lg py-2.5 text-xs font-medium
                                       transition-all hover:scale-105 active:scale-95"
                        >
                            ADV
                        </button>
                    </div>
                </div>
            )}

            {/* Messages / Roll Log */}
            <div className="flex-1 overflow-y-auto p-3 space-y-2 min-h-0">
                {chatMessages.length === 0 ? (
                    <div className="flex items-center justify-center h-full text-stone-600 text-sm">
                        {activeTab === 'dice' ? 'Roll some dice! 🎲' : 'No messages yet...'}
                    </div>
                ) : (
                    <>
                        {chatMessages
                            .filter((msg) => activeTab === 'chat' || msg.isRoll)
                            .map(renderMessage)}
                        <div ref={chatEndRef} />
                    </>
                )}
            </div>

            {/* Input */}
            <div className="p-3 border-t border-stone-700/30">
                <div className="flex gap-2">
                    <input
                        type="text"
                        value={message}
                        onChange={(e) => setMessage(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                        placeholder={activeTab === 'dice' ? 'Type a roll (e.g., 2d6+3)...' : 'Type a message...'}
                        className="flex-1 bg-stone-800 border border-stone-600/50 rounded-lg px-3 py-2
                                   text-stone-200 text-sm placeholder-stone-500
                                   focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                    />
                    <button
                        onClick={handleSendMessage}
                        disabled={!message.trim()}
                        className="bg-blue-600 hover:bg-blue-500 disabled:opacity-30 
                                   text-white rounded-lg px-3 transition-colors"
                    >
                        <Send className="w-4 h-4" />
                    </button>
                </div>
                {activeTab === 'dice' && (
                    <p className="text-stone-600 text-[10px] mt-1.5">
                        Supports: 2d6+3, d20, 4d8-2, etc.
                    </p>
                )}
            </div>
        </div>
    );
}
